import {materialType} from '/material-model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg aria-hidden="true"><use href="#i-${n}"/></svg>`;
export function initTrash({uploads,getDrafts,restoreDraft,purgeDrafts,toast}){
 const root=document.querySelector('#trash-content');let query='',busy=false;
 root.innerHTML=`<div class="view-heading"><div><span class="micro-label">A SECOND CHANCE FOR YOUR IDEAS</span><h2>回收站</h2><p>已移除的作品与上传素材，在这里统一整理。</p></div><button id="unified-empty-trash" class="outline-button">${icon('trash')}一键清空</button></div><div class="upload-toolbar"><label class="upload-search glass">${icon('search')}<input id="trash-search" type="search" aria-label="搜索回收站" placeholder="搜索作品或素材名称…"></label><span id="unified-trash-count" class="micro-label"></span></div><div id="unified-trash-list" class="unified-trash-list"></div><dialog id="unified-trash-dialog" class="upload-dialog glass"><h3>清空回收站？</h3><p id="unified-trash-description"></p><p>清空后无法恢复。上传文件将从云端删除并释放存储空间，作品也会从关联专辑移除。</p><div class="trash-dialog-actions"><button id="unified-trash-cancel" class="outline-button">取消</button><button id="unified-trash-confirm" class="primary-button">确认清空</button></div></dialog>`;
 const $=s=>root.querySelector(s);
 const entries=()=>[...getDrafts().filter(d=>d.trashed).map(d=>({id:d.id,title:d.title,type:d.type||'songs',source:'draft'})),...uploads.trashItems().map(a=>({id:a.id,title:a.title,type:materialType(a.kind.replace('upload-','')),source:'upload'}))];
 function render(){const all=entries(),list=all.filter(a=>a.title.toLowerCase().includes(query.toLowerCase()));$('#unified-empty-trash').disabled=busy||!all.length;$('#unified-trash-count').textContent=all.length+' 项';const badge=document.querySelector('#material-trash-count');if(badge)badge.textContent=all.length;$('#unified-trash-list').innerHTML=list.length?list.map(a=>`<article class="trash-item glass"><div class="trash-item-symbol">${icon(a.type==='abc'?'score':['speech'].includes(a.type)?'voice':'music')}</div><div><h3>${esc(a.title)}</h3><p>${a.source==='draft'?'创作作品':'上传素材'} · ${esc(({songs:'音乐',music:'音乐',speech:'语音',sounds:'音效',abc:'ABC 乐谱'})[a.type]||a.type)}</p></div><button class="outline-button" data-trash-restore="${esc(a.id)}" data-trash-source="${a.source}" ${busy?'disabled':''}>恢复</button></article>`).join(''):`<div class="upload-empty glass">${icon('trash')}<h3>${query?'没有找到匹配内容':'回收站是空的'}</h3><p>${query?'试试其他名称。':'删除的作品和素材会显示在这里，可以恢复。'}</p></div>`;}
 let snapshot=[];$('#unified-empty-trash').onclick=()=>{snapshot=entries();$('#unified-trash-description').textContent='将永久清理 '+snapshot.length+' 项：'+snapshot.filter(a=>a.source==='draft').length+' 个作品、'+snapshot.filter(a=>a.source==='upload').length+' 份上传素材。';$('#unified-trash-dialog').showModal();};$('#unified-trash-cancel').onclick=()=>$('#unified-trash-dialog').close();
 $('#unified-trash-confirm').onclick=async()=>{if(busy)return;busy=true;$('#unified-trash-confirm').disabled=true;$('#unified-trash-cancel').disabled=true;render();try{const ids=snapshot.filter(a=>a.source==='upload').map(a=>a.id),failed=await uploads.purge(ids);await purgeDrafts(new Set(snapshot.filter(a=>a.source==='draft').map(a=>a.id)));$('#unified-trash-dialog').close();toast(failed?'部分素材未能清理，已保留在回收站，可稍后重试。':'回收站已清空。');}catch(e){toast(e.message);}finally{busy=false;$('#unified-trash-confirm').disabled=false;$('#unified-trash-cancel').disabled=false;render();}};
 $('#trash-search').oninput=e=>{query=e.target.value;render();};root.addEventListener('click',e=>{const b=e.target.closest('[data-trash-restore]');if(!b||busy)return;if(b.dataset.trashSource==='draft')restoreDraft(b.dataset.trashRestore);else uploads.restore(b.dataset.trashRestore);render();toast('已恢复到原来的位置。');});
 return {render,show:async()=>{render();await uploads.show();render();}};
}
